fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    
    for i in 0..v1.len() {
        result.push(v1[i]);
    }
    
    for i in 0..v2.len() {
        result.push(v2[i]);
    }
    
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(first.len() - 1 + second.len());
    
    let mut i = 0;
    while i < first.len() - 1 {
        result.push(first[i]);
        i += 1;
    }
    
    let mut j = 0;
    while j < second.len() {
        result.push(second[j]);
        j += 1;
    }
    
    result
}